def move_id(move: chess.Move) -> int:
    if move == chess.Move.null() or move.drop is not None:
        raise ValueError('Chỉ hỗ trợ nước cờ vua tiêu chuẩn.')
    return (
        (move.from_square * 64 + move.to_square) * 5
        + PROMOTIONS.index(move.promotion)
    )

def id_move(index: int) -> chess.Move:
    if not 0 <= index < ACTION_SIZE:
        raise ValueError('Mã hành động ngoài phạm vi.')
    pair, promotion = divmod(index, 5)
    source, target = divmod(pair, 64)
    return chess.Move(source, target, promotion=PROMOTIONS[promotion])

def masked_logits(logits, legal_mask):
    if not bool(legal_mask.any(dim=-1).all()):
        raise ValueError('Mẫu huấn luyện phải có ít nhất một nước hợp lệ.')
    return logits.masked_fill(~legal_mask, torch.finfo(logits.dtype).min)

from dataclasses import dataclass

@dataclass
class ModelConfig:
    kind: str = 'cnn'
    width: int = 32
    hidden: int = 128

def forward(self, x):
    features = self.trunk(x)
    return self.policy(features), self.value_head(features).squeeze(-1)

def value(self, x):
    # Search and TD need no 20,480-action policy projection.
    return self.value_head(self.trunk(x)).squeeze(-1)

def td_target(next_value, terminal_reward=None, gamma=1.):
    if terminal_reward is not None:
        return torch.full_like(next_value, terminal_reward)
    return -gamma * next_value.detach()
